'use strict';

const path = require('node:path');

const STATE_DIRECTORY_ERROR_CODES = Object.freeze({
  INVALID_ROOT: 'INVALID_STATE_DIRECTORY_ROOT',
  INVALID_PLATFORM: 'INVALID_STATE_DIRECTORY_PLATFORM',
  INVALID_ACCOUNT_REFERENCE: 'INVALID_STATE_DIRECTORY_ACCOUNT_REFERENCE',
  PATH_ESCAPE: 'STATE_DIRECTORY_PATH_ESCAPE',
});

const PLATFORM_DIRECTORY_NAMES = Object.freeze({
  tiktok_shop: 'tiktok-shop',
  tiktok: 'tiktok',
  instagram: 'instagram',
  x: 'x',
});

const PLATFORM_ALIASES = Object.freeze({
  'tiktok-shop': 'tiktok_shop',
});

// Account references are generated by createAccountReference().  Keeping this
// boundary UUID-only prevents usernames, emails, cookies, and access tokens
// from accidentally becoming filesystem paths or process-profile names.
const ACCOUNT_REFERENCE_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

class StateDirectoryError extends Error {
  constructor(code, message) {
    // Do not include a user-supplied path or account value here: callers can
    // safely surface these errors without accidentally logging credentials.
    super(message);
    this.name = 'StateDirectoryError';
    this.code = code;
  }
}

function canonicalPlatform(platform) {
  if (typeof platform !== 'string') {
    throw new StateDirectoryError(STATE_DIRECTORY_ERROR_CODES.INVALID_PLATFORM, 'A supported platform is required');
  }
  const normalized = PLATFORM_ALIASES[platform] || platform;
  if (!Object.prototype.hasOwnProperty.call(PLATFORM_DIRECTORY_NAMES, normalized)) {
    throw new StateDirectoryError(STATE_DIRECTORY_ERROR_CODES.INVALID_PLATFORM, 'A supported platform is required');
  }
  return normalized;
}

function assertOpaqueAccountReference(accountRef) {
  if (typeof accountRef !== 'string' || !ACCOUNT_REFERENCE_PATTERN.test(accountRef)) {
    throw new StateDirectoryError(
      STATE_DIRECTORY_ERROR_CODES.INVALID_ACCOUNT_REFERENCE,
      'An opaque account reference is required',
    );
  }
}

function normalizedAbsoluteRoot(stateRoot) {
  if (typeof stateRoot !== 'string' || stateRoot.trim() === '' || !path.isAbsolute(stateRoot)) {
    throw new StateDirectoryError(STATE_DIRECTORY_ERROR_CODES.INVALID_ROOT, 'An absolute local state directory root is required');
  }
  return path.resolve(stateRoot);
}

function isNestedWithin(root, candidate) {
  const relative = path.relative(root, candidate);
  return relative !== '' && !relative.startsWith(`..${path.sep}`) && relative !== '..' && !path.isAbsolute(relative);
}

/**
 * Returns the only approved directory for a platform/account browser state.
 * The function deliberately does not create the directory; callers own that
 * side effect and can apply their normal filesystem error handling.
 */
function resolvePlatformStateDirectory({ stateRoot, platform, accountRef }) {
  const root = normalizedAbsoluteRoot(stateRoot);
  const platformId = canonicalPlatform(platform);
  assertOpaqueAccountReference(accountRef);

  const directory = path.resolve(root, PLATFORM_DIRECTORY_NAMES[platformId], accountRef);
  if (!isNestedWithin(root, directory)) {
    throw new StateDirectoryError(STATE_DIRECTORY_ERROR_CODES.PATH_ESCAPE, 'Resolved state directory is outside its root');
  }

  return Object.freeze({
    root,
    platform: platformId,
    accountRef,
    directory,
  });
}

module.exports = {
  PLATFORM_DIRECTORY_NAMES,
  STATE_DIRECTORY_ERROR_CODES,
  StateDirectoryError,
  resolvePlatformStateDirectory,
};
